    {
      "claim": "The Fourth Geneva Convention applies to any territory occupied by a High Contracting Party, irrespective of the prior sovereign status of that territory.",
      "reasoning": "Article 2, paragraph 2 of the Fourth Geneva Convention (a universally accepted provision of customary IHL) states that the Convention applies to the occupation of the territory of a High Contracting Party, regardless of whether the occupying power recognizes the prior sovereign. This principle has been affirmed in the practice of states and the jurisprudence of international tribunals, establishing that the existence of a prior recognized sovereign is not a condition for applicability.",
      "citations": []
    },
    {
      "claim": "Both Israel and Jordan were parties to the Fourth Geneva Convention at the time of the 1967 occupation, so the occupied Palestinian territories constitute \"the territory of a High Contracting Party\" for purposes of Article 2(2).",
      "reasoning": "Since Jordan had ratified the Fourth Geneva Convention, its former mandate territory, including the West Bank and East Jerusalem, is considered the territory of a High Contracting Party. The occupation by Israel therefore triggers the Convention’s provisions, independent of any dispute over Jordan’s sovereignty over the area.",
      "citations": []
    },
    {
      "claim": "The Rome Statute’s incorporation of Common Article 3 demonstrates that the Geneva Conventions are deemed applicable to the situation in the occupied Palestinian territories.",
      "reasoning": "Article 8(2)(c) of the Rome Statute expressly makes “serious violations of article 3 common to the four Geneva Conventions” punishable in non‑international armed conflicts. The ICC has asserted jurisdiction over alleged war‑crimes committed in the occupied Palestinian territories, indicating that the Court treats the Geneva Conventions as applicable to that context.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8(2)(c)",
          "quoted_text": "In the case of an armed conflict not of an international character, serious violations of article 3 common to the four Geneva Conventions of 12 August 1949, namely, any of the following acts..."
        }
      ]
    },
    {
      "claim": "Additional Protocol I confirms that the Geneva Conventions apply to the occupied Palestinian territories, because the Protocol applies in the same situations as the Conventions.",
      "reasoning": "Article 1 of Additional Protocol I states that the Protocol “reaffirms and supplements the provisions of the four Geneva Conventions” and “shall apply in the same situations as those referred to in these provisions.” By accepting the Protocol, a state acknowledges the applicability of the Conventions to any occupation it is involved in, including the 1967 occupation.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "ap_iii",
          "article": "1",
          "quoted_text": "This Protocol reaffirms and supplements the provisions of the four Geneva Conventions of 12 August 1949 (\"the Geneva Conventions\") and, where applicable, of their two Additional Protocols of 8 June 1977 (\"the 1977 Additional Protocols\")...shall apply in the same situations as those referred to in these provisions."
        }
      ]
    },
    {
      "claim": "Under the Convention on Certain Conventional Weapons (CCW), a High Contracting Party may accept the applicability of the Geneva Conventions even when the other party is not a party, confirming that Israel is bound by the Fourth Geneva Convention in the occupied territories.",
      "reasoning": "Article 7(4) of the CCW provides that when an authority accepts and applies the obligations of the Geneva Conventions, “the Geneva Conventions … are brought into force for the parties to the conflict with immediate effect.” Israel’s acceptance of the Conventions’ obligations, irrespective of Jordan’s sovereign status, therefore makes the Fourth Geneva Convention applicable to the occupied Palestinian territories.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "ccw",
          "article": "7(4)",
          "quoted_text": "Such an acceptance and application shall have in relation to that conflict the following effects: (i) the Geneva Conventions and this Convention and its relevant annexed Protocols are brought into force for the parties to the conflict with immediate effect;"
        }
      ]
    }
  ]
}

